private static int getVolumeFromManager(AudioManager audioManager, @C.StreamType int streamType) {
  try {
    return audioManager.getStreamVolume(streamType);
  } catch (IllegalArgumentException e) {
    // Handle the exception, e.g., log it or return a default value
    System.out.println("Invalid stream type: " + e.getMessage());
    return 0; // or any other appropriate default value
  }
